function withQuery(path: string, query: Record<string, string | number | boolean | undefined>): string {
  const params = new URLSearchParams();
  Object.entries(query).forEach(([key, value]) => {
    if (value === undefined || value === null) return;
    if (typeof value === 'boolean') {
      if (value) params.set(key, 'true');
      return;
    }
    if (typeof value === 'number') {
      if (Number.isFinite(value)) params.set(key, String(value));
      return;
    }
    const text = value.trim();
    if (text) params.set(key, text);
  });
  const qs = params.toString();
  return qs ? `${path}?${qs}` : path;
}

export async function listProductionNorms(
  query: Record<string, string | number | boolean | undefined>,
): Promise<ProductionNormListItem[]> {
  const res = await apiClient.get<BffResponse<ProductionNormListItem[]>>(withQuery(BASE, query));
  return unwrap(res);
}

export async function getProductionNorm(sttRec: string): Promise<ProductionNorm> {
  const res = await apiClient.get<BffResponse<ProductionNorm>>(`${BASE}/${encodeURIComponent(sttRec)}`);
  return unwrap(res);
}

export async function createProductionNorm(body: ProductionNormWrite): Promise<ProductionNorm> {
  const res = await apiClient.post<BffResponse<ProductionNorm>>(BASE, body);
  return unwrap(res);
}

export async function updateProductionNorm(sttRec: string, body: ProductionNormWrite): Promise<ProductionNorm> {
  const res = await apiClient.put<BffResponse<ProductionNorm>>(
    `${BASE}/${encodeURIComponent(sttRec)}`,
    body,
  );
  return unwrap(res);
}
