import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { format, parseISO } from 'date-fns';
import { Button, Checkbox, Input, SearchInput, Select } from '@linm-soft-org/linm-web-common-components';
import { createContractSearchConfig } from '../../../components/search/contractSearchConfig';
import { createMaterialSearchConfig } from '../../../components/search/materialSearchConfig';
import { useInAppNavigate } from '../../../router/useInAppNavigate';
import { GT } from '../../../router/paths';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import type { MaterialDto } from '../../../services/kt/models';
import type { ContractDto } from '../../../services/sales/models';
import { listProductionNorms, type ProductionNormListItem } from '../../../services/gt/productionNorms';
import df from '../../../styles/documentForm.module.css';

const LIST = GT.DINH_MUC_SAN_PHAM;

interface SearchState {
  ngayCt1: string;
  ngayCt2: string;
  soCt1: string;
  soCt2: string;
  maKh: string;
  maKho: string;
  maVt: string;
  dienGiai: string;
  maGd: string;
  maPost: string;
  maPhi: string;
  maVv: string;
  maHd: string;
  maSp: string;
  maKu: string;
  maTtln: string;
  maTtcp: string;
  maBp: string;
  maHs: string;
  maCd: string;
  maTd1: string;
  maTd2: string;
  maTd3: string;
  maTd4: string;
  maTd5: string;
  locNsd: boolean;
}

const emptySearch = (): SearchState => ({
  ngayCt1: '',
  ngayCt2: '',
  soCt1: '',
  soCt2: '',
  maKh: '',
  maKho: '',
  maVt: '',
  dienGiai: '',
  maGd: '',
  maPost: '9',
  maPhi: '',
  maVv: '',
  maHd: '',
  maSp: '',
  maKu: '',
  maTtln: '',
  maTtcp: '',
  maBp: '',
  maHs: '',
  maCd: '',
  maTd1: '',
  maTd2: '',
  maTd3: '',
  maTd4: '',
  maTd5: '',
  locNsd: false,
});

const moneyFormat = new Intl.NumberFormat('vi-VN', { maximumFractionDigits: 4 });

function showMoney(value: number | null | undefined): string {
  return moneyFormat.format(value ?? 0);
}

function formatDate(value: string | null | undefined): string {
  if (!value) return '';
  try {
    const parsed = parseISO(value);
    if (Number.isNaN(parsed.getTime())) return value;
    return format(parsed, 'dd/MM/yyyy');
  } catch {
    return value;
  }
}

function buildSearchQuery(search: SearchState): Record<string, string | boolean> {
  const query: Record<string, string | boolean> = { maPost: search.maPost === '3' ? '3' : '9' };
  const textKeys: Array<keyof SearchState> = [
    'ngayCt1', 'ngayCt2', 'soCt1', 'soCt2', 'maKh', 'maKho', 'maVt', 'dienGiai',
    'maPhi', 'maVv', 'maHd', 'maSp', 'maKu', 'maTtln', 'maTtcp', 'maBp', 'maHs', 'maCd',
    'maTd1', 'maTd2', 'maTd3', 'maTd4', 'maTd5',
  ];
  textKeys.forEach(key => {
    const value = String(search[key]).trim();
    if (value) query[key] = value;
  });
  if (search.maGd === '2') query.maGd = '2';
  if (search.locNsd) query.locNsd = true;
  return query;
}

function Field(props: {
  label: string;
  testId: string;
  value: string;
  onChange: (event: React.ChangeEvent<HTMLInputElement>) => void;
  maxLength?: number;
  type?: string;
  span?: boolean;
}) {
  return (
    <div className={props.span ? `${df.field} ${df.spanCol2}` : df.field}>
      <label className={df.label} htmlFor={props.testId}>{props.label}</label>
      <Input
        id={props.testId}
        type={props.type}
        maxLength={props.maxLength}
        data-testid={props.testId}
        value={props.value}
        onChange={props.onChange}
      />
    </div>
  );
}

const GtDm1ListPage: React.FC = () => {
  const navigate = useInAppNavigate();
  const materialSearch = useMemo(() => createMaterialSearchConfig(), []);
  const contractSearch = useMemo(() => createContractSearchConfig(), []);
  const requestSeq = useRef(0);
  const [search, setSearch] = useState<SearchState>(emptySearch);
  const [applied, setApplied] = useState<SearchState>(emptySearch);
  const [filtering, setFiltering] = useState(false);
  const [items, setItems] = useState<ProductionNormListItem[]>([]);
  const [selectedSttRec, setSelectedSttRec] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const keepSelection = (rows: ProductionNormListItem[], current: string) => {
    if (rows.some(row => row.sttRec === current)) return current;
    return '';
  };

  const runLoad = useCallback(async (
    query: Record<string, string | number | boolean | undefined>,
    current: string,
  ) => {
    const seq = ++requestSeq.current;
    setLoading(true);
    setError('');
    try {
      const rows = await listProductionNorms(query);
      if (seq !== requestSeq.current) return;
      setItems(rows);
      setSelectedSttRec(keepSelection(rows, current));
    } catch (err) {
      if (seq !== requestSeq.current) return;
      setItems([]);
      setSelectedSttRec('');
      setError(getApiErrorMessage(err, 'Không tải được danh sách định mức sản phẩm sản xuất'));
    } finally {
      if (seq === requestSeq.current) setLoading(false);
    }
  }, []);

  useEffect(() => {
    void runLoad({ loadTop: 5 }, '');
  }, [runLoad]);

  const setText = (key: keyof SearchState) => (event: React.ChangeEvent<HTMLInputElement>) => {
    setSearch(prev => ({ ...prev, [key]: event.target.value }));
  };

  const onSearch = () => {
    setFiltering(true);
    setApplied(search);
    void runLoad(buildSearchQuery(search), selectedSttRec);
  };

  const onRefresh = () => {
    if (filtering) void runLoad(buildSearchQuery(applied), selectedSttRec);
    else void runLoad({ loadTop: 5 }, selectedSttRec);
  };

  const onEnter = (event: React.KeyboardEvent) => {
    if (event.key !== 'Enter') return;
    const target = event.target;
    if (!(target instanceof HTMLElement)) return;
    if (target.closest('[data-skip-enter-search]')) return;
    if (target instanceof HTMLInputElement || target instanceof HTMLSelectElement) {
      event.preventDefault();
      onSearch();
    }
  };

  const noSelection = !selectedSttRec;

  return (
    <div className={df.page} data-testid="ct-gt-dm1-list">
      <h1 data-testid="ct-gt-dm1-title">Định mức sản phẩm sản xuất</h1>
      <div className={df.headerActions} data-testid="ct-gt-dm1-toolbar">
        <Button variant="secondary" data-testid="ct-gt-dm1-toolbar-refresh-btn" onClick={onRefresh}>Làm mới</Button>
        <Button variant="primary" data-testid="ct-gt-dm1-search-btn" onClick={onSearch}>Tìm</Button>
        <Button variant="primary" data-testid="ct-gt-dm1-toolbar-add-btn" onClick={() => navigate(`${LIST}/them`)}>Thêm</Button>
        <Button variant="secondary" data-testid="ct-gt-dm1-toolbar-edit-btn" disabled={noSelection} onClick={() => navigate(`${LIST}/${selectedSttRec}`)}>Sửa</Button>
        <Button variant="secondary" data-testid="ct-gt-dm1-toolbar-view-btn" disabled={noSelection} onClick={() => navigate(`${LIST}/${selectedSttRec}?mode=view`)}>Xem</Button>
        <Button variant="secondary" data-testid="ct-gt-dm1-toolbar-copy-btn" disabled={noSelection} onClick={() => navigate(`${LIST}/them?copyFrom=${encodeURIComponent(selectedSttRec)}`)}>Sao chép</Button>
      </div>

      <section className={df.section} data-testid="ct-gt-dm1-search">
        <h2 className={df.sectionTitle}>Tìm kiếm</h2>
        <div className={df.row4} onKeyDown={onEnter}>
          <Field label="Ngày C.từ từ" testId="ct-gt-dm1-search-ngayCt1" type="date" value={search.ngayCt1} onChange={setText('ngayCt1')} />
          <Field label="Ngày C.từ đến" testId="ct-gt-dm1-search-ngayCt2" type="date" value={search.ngayCt2} onChange={setText('ngayCt2')} />
          <Field label="Số C.từ từ" testId="ct-gt-dm1-search-soCt1" maxLength={30} value={search.soCt1} onChange={setText('soCt1')} />
          <Field label="Số C.từ đến" testId="ct-gt-dm1-search-soCt2" maxLength={30} value={search.soCt2} onChange={setText('soCt2')} />
          <Field label="Đối tượng" testId="ct-gt-dm1-search-maKh" maxLength={30} value={search.maKh} onChange={setText('maKh')} />
          <Field label="Kho" testId="ct-gt-dm1-search-maKho" maxLength={30} value={search.maKho} onChange={setText('maKho')} />
          <div className={df.field} data-testid="ct-gt-dm1-search-maVt" data-skip-enter-search>
            <span className={df.label}>Nguyên vật liệu</span>
            <SearchInput
              config={materialSearch}
              value={search.maVt}
              primaryDisplay={search.maVt}
              showLabel={false}
              showSecondaryInput={false}
              placeholder="Nguyên vật liệu"
              onChange={(item: MaterialDto) => setSearch(prev => ({ ...prev, maVt: item.code }))}
              onClear={() => setSearch(prev => ({ ...prev, maVt: '' }))}
            />
          </div>
          <Field label="Diễn giải" testId="ct-gt-dm1-search-dienGiai" maxLength={200} span value={search.dienGiai} onChange={setText('dienGiai')} />
          <Select
            label="Loại giao dịch"
            data-testid="ct-gt-dm1-search-maGd"
            value={search.maGd}
            options={[{ value: '', label: 'Tất cả' }, { value: '2', label: 'Định mức sản xuất' }]}
            onChange={event => setSearch(prev => ({ ...prev, maGd: event.target.value }))}
          />
        </div>
      </section>

      <section className={df.section} data-testid="ct-gt-dm1-search-extra">
        <h2 className={df.sectionTitle}>Điều kiện thêm</h2>
        <div className={df.row4} onKeyDown={onEnter}>
          <Select
            label="Trạng thái"
            data-testid="ct-gt-dm1-search-maPost"
            value={search.maPost}
            options={[{ value: '3', label: 'Lập định mức' }, { value: '9', label: 'Định mức đã duyệt' }]}
            onChange={event => setSearch(prev => ({ ...prev, maPost: event.target.value }))}
          />
          <Field label="Phí" testId="ct-gt-dm1-search-maPhi" maxLength={30} value={search.maPhi} onChange={setText('maPhi')} />
          <Field label="Vụ việc" testId="ct-gt-dm1-search-maVv" maxLength={30} value={search.maVv} onChange={setText('maVv')} />
          <div className={df.field} data-testid="ct-gt-dm1-search-maHd" data-skip-enter-search>
            <span className={df.label}>Hợp đồng</span>
            <SearchInput
              config={contractSearch}
              value={search.maHd}
              primaryDisplay={search.maHd}
              showLabel={false}
              showSecondaryInput={false}
              placeholder="Hợp đồng"
              onChange={(item: ContractDto) => setSearch(prev => ({ ...prev, maHd: item.code }))}
              onClear={() => setSearch(prev => ({ ...prev, maHd: '' }))}
            />
          </div>
          <Field label="Sản phẩm" testId="ct-gt-dm1-search-maSp" maxLength={30} value={search.maSp} onChange={setText('maSp')} />
          <Field label="Khế ước" testId="ct-gt-dm1-search-maKu" maxLength={30} value={search.maKu} onChange={setText('maKu')} />
          <Field label="Trung tâm lợi nhuận" testId="ct-gt-dm1-search-maTtln" maxLength={30} value={search.maTtln} onChange={setText('maTtln')} />
          <Field label="Trung tâm chi phí" testId="ct-gt-dm1-search-maTtcp" maxLength={30} value={search.maTtcp} onChange={setText('maTtcp')} />
          <Field label="Bộ phận" testId="ct-gt-dm1-search-maBp" maxLength={30} value={search.maBp} onChange={setText('maBp')} />
          <Field label="Hồ sơ" testId="ct-gt-dm1-search-maHs" maxLength={30} value={search.maHs} onChange={setText('maHs')} />
          <Field label="Công đoạn" testId="ct-gt-dm1-search-maCd" maxLength={30} value={search.maCd} onChange={setText('maCd')} />
          <Field label="Mã tự do 1" testId="ct-gt-dm1-search-maTd1" maxLength={30} value={search.maTd1} onChange={setText('maTd1')} />
          <Field label="Mã tự do 2" testId="ct-gt-dm1-search-maTd2" maxLength={30} value={search.maTd2} onChange={setText('maTd2')} />
          <Field label="Mã tự do 3" testId="ct-gt-dm1-search-maTd3" maxLength={30} value={search.maTd3} onChange={setText('maTd3')} />
          <Field label="Mã tự do 4" testId="ct-gt-dm1-search-maTd4" maxLength={30} value={search.maTd4} onChange={setText('maTd4')} />
          <Field label="Mã tự do 5" testId="ct-gt-dm1-search-maTd5" maxLength={30} value={search.maTd5} onChange={setText('maTd5')} />
          <div>
            <Checkbox
              label="Chỉ chứng từ của tôi"
              data-testid="ct-gt-dm1-search-locNsd"
              checked={search.locNsd}
              onChange={event => setSearch(prev => ({ ...prev, locNsd: event.target.checked }))}
            />
          </div>
        </div>
      </section>

      {error ? <div className={df.errorBanner}>{error}</div> : null}
      {loading ? <div className={df.loading}>Đang tải...</div> : null}
      <div className={df.tableWrapper}>
        <table className={df.linesTable} data-testid="ct-gt-dm1-grid">
          <thead>
            <tr>
              <th>Số C.từ</th>
              <th>Ngày C.từ</th>
              <th>Mã sản phẩm</th>
              <th>Tên sản phẩm</th>
              <th>Tổng Phát sinh</th>
              <th>Tổng Ps NT</th>
              <th>Ngoại tệ</th>
            </tr>
          </thead>
          <tbody>
            {items.map(row => (
              <tr
                key={row.sttRec}
                data-testid={`ct-gt-dm1-row-${row.sttRec}`}
                aria-selected={row.sttRec === selectedSttRec}
                style={row.sttRec === selectedSttRec ? { background: 'var(--ds-color-primary-bg, rgba(13, 110, 253, 0.08))' } : undefined}
                onClick={() => setSelectedSttRec(row.sttRec)}
              >
                <td>{row.soCt}</td>
                <td>{formatDate(row.ngayCt)}</td>
                <td>{row.maSpH}</td>
                <td>{row.tenSpH}</td>
                <td>{showMoney(row.tTien)}</td>
                <td>{showMoney(row.tTienNt)}</td>
                <td>{row.maNt}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {!loading && items.length === 0 ? (
        <div data-testid="ct-gt-dm1-empty">
          {filtering ? 'Không tìm thấy định mức sản phẩm sản xuất' : 'Không có định mức sản phẩm sản xuất'}
        </div>
      ) : null}
    </div>
  );
};

export default GtDm1ListPage;
